using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Threading;

// Own MIDI handles on one worker. Painting and log IO never delay receive-buffer recycling.
public sealed partial class FaderConnection : IDisposable {
 readonly uint inputId,outputId;readonly int device;readonly object gate=new object();
 readonly int?[] pans=new int?[96],panWrites=new int?[96];readonly DateTime[] panReceived=new DateTime[96];readonly int?[] writes=new int?[96]; int writeCursor; readonly int?[] values=new int?[96];readonly DateTime[] received=new DateTime[96];
 readonly int?[] meters=new int?[96];readonly DateTime[] meterReceived=new DateTime[96];int? inputPoint,outputPoint;DateTime inputPointReceived,outputPointReceived;int meterFrames;readonly Thread worker;readonly ManualResetEventSlim ready=new ManualResetEventSlim();
 volatile bool stopping;volatile int bank;volatile string error;int scans;double lastScan;
 public readonly ConcurrentQueue<string> Messages=new ConcurrentQueue<string>();
 public string Error{get{return error;}}
 public FaderConnection(uint input,uint output,int dev){inputId=input;outputId=output;device=dev;worker=new Thread(Run){IsBackground=true,Name="DM2000 fader reader"};worker.Start();if(!ready.Wait(3000)){Dispose();throw new TimeoutException("Opening the console timed out");}if(error!=null){Dispose();throw new InvalidOperationException(error);}}
 public void CopyPan(int?[] destination,DateTime[] dates){lock(gate){Array.Copy(pans,destination,96);Array.Copy(panReceived,dates,96);}}public void WritePan(int channel,int value){if(channel<0||channel>95||value< -63||value>63)throw new ArgumentOutOfRangeException();lock(gate){if(ZeroInputsBusy)throw new InvalidOperationException("Stop zeroing inputs before adjusting pan.");if(stopping||error!=null||!pans[channel].HasValue||(DateTime.UtcNow-panReceived[channel]).TotalSeconds>2)throw new InvalidOperationException("Pan connection is not current. Reconnect before adjusting.");panWrites[channel]=value;}}public void WriteFader(int channel,int raw){if(channel<0||channel>95||raw<0||raw>1023)throw new ArgumentOutOfRangeException();lock(gate){if(ZeroInputsBusy)throw new InvalidOperationException("Stop zeroing inputs before adjusting faders.");if(stopping||error!=null||!values[channel].HasValue||(DateTime.UtcNow-received[channel]).TotalSeconds>2)throw new InvalidOperationException("Fader connection is not current. Reconnect before adjusting.");writes[channel]=raw;}} public void SetBank(int first){if(first!=0&&first!=24&&first!=48&&first!=72)throw new ArgumentOutOfRangeException();bank=first;}
 public void Copy(int?[] destination,DateTime[] dates){lock(gate){Array.Copy(values,destination,96);Array.Copy(received,dates,96);}}
 public int MeterFrames{get{lock(gate)return meterFrames;}} public void CopyMeters(int?[] destination,DateTime[] dates,out int? inp,out int? outp){lock(gate){Array.Copy(meters,destination,96);Array.Copy(meterReceived,dates,96);inp=(DateTime.UtcNow-inputPointReceived).TotalSeconds<3?inputPoint:null;outp=(DateTime.UtcNow-outputPointReceived).TotalSeconds<3?outputPoint:null;}} public double LastBankReadMs{get{lock(gate)return lastScan;}}
 public int CompletedScans{get{lock(gate)return scans;}}
 void Run(){try{using(var input=new MidiInput(inputId))using(var output=new FaderReader(outputId)){ready.Set();var clock=Stopwatch.StartNew();bool[] waiting=new bool[24];int active=-1,pending=0;double next=0,started=0,meterRenew=0,pointPoll=0,nextWrite=0,nextPan=0;int panCursor=0;while(!stopping){input.Pump();byte[] packet;while(input.Packets.TryDequeue(out packet)){if(packet.Length<3||(packet[2]&15)!=device)continue;ExtraPacket(packet);int first;int[] levels;if(MeterProtocol.TryRead(packet,out first,out levels)){lock(gate){for(int m=0;m<levels.Length;m++){meters[first+m]=levels[m];meterReceived[first+m]=DateTime.UtcNow;}meterFrames++;}continue;}bool isOutput;int meterPoint;if(MeterProtocol.TryPoint(packet,out isOutput,out meterPoint)){lock(gate){if(isOutput){outputPoint=meterPoint;outputPointReceived=DateTime.UtcNow;}else{inputPoint=meterPoint;inputPointReceived=DateTime.UtcNow;}}continue;}int panChannel,panValue;if(PanProtocol.TryRead(packet,out panChannel,out panValue)){lock(gate){pans[panChannel]=panValue;panReceived[panChannel]=DateTime.UtcNow;}continue;}int c,raw;if(!FaderProtocol.TryRead(packet,out c,out raw)||(packet[2]&15)!=device)continue;bool changed;lock(gate){changed=!values[c].HasValue||values[c].Value!=raw;values[c]=raw;received[c]=DateTime.UtcNow;}if(c>=active&&c<active+24&&waiting[c-active]){waiting[c-active]=false;pending--;if(pending==0){lock(gate){lastScan=clock.Elapsed.TotalMilliseconds-started;scans++;}}}if(changed&&Messages.Count<512)Messages.Enqueue("Input "+(c+1)+": "+FaderProtocol.Label(raw));}string unused;while(input.Messages.TryDequeue(out unused)){}double now=clock.Elapsed.TotalMilliseconds;if(now>=nextWrite){lock(gate){if(!stopping){int sent=0;for(int n=0;n<96&&sent<8;n++){int c=(writeCursor+n)%96;if(writes[c].HasValue){int value=writes[c].Value;writes[c]=null;if((DateTime.UtcNow-received[c]).TotalSeconds<=2){output.SetFader(c,value,device);output.Read(c,device);sent++;}}if(panWrites[c].HasValue){int value=panWrites[c].Value;panWrites[c]=null;if((DateTime.UtcNow-panReceived[c]).TotalSeconds<=2){output.SetPan(c,value,device);output.ReadPan(c,device);sent++;}}}writeCursor=(writeCursor+8)%96;}}nextWrite=now+20;}if(now>=meterRenew){output.SubscribeMeters(device);meterRenew=now+5000;}if(now>=pointPoll){output.ReadMeterPoint(false,device);output.ReadMeterPoint(true,device);pointPoll=now+500;}int requested=bank;if(requested!=active){panCursor=0;nextPan=0;if(mixerView>=4||sendAux>=0)active=requested;}if(mixerView<4&&sendAux<0&&(requested!=active||((pending==0||now-started>=250)&&now>=next))){active=requested;pending=24;started=now;next=now+50;for(int i=0;i<24;i++){waiting[i]=true;output.Read(active+i,device);}}if(mixerView<4&&now>=nextPan){for(int i=0;i<4;i++)output.ReadPan(requested+(panCursor++%24),device);nextPan=now+40;}TickExtra(output,now);Thread.Sleep(1);}}}catch(Exception e){error=e.Message;}finally{ready.Set();}}
 public void Dispose(){lock(gate){stopping=true;Array.Clear(writes,0,96);Array.Clear(panWrites,0,96);}if(worker.IsAlive&&!worker.Join(3000))throw new TimeoutException("Console reader did not stop");lock(gate){ClearExtra();Array.Clear(values,0,96);Array.Clear(pans,0,96);Array.Clear(panReceived,0,96);Array.Clear(received,0,96);Array.Clear(meters,0,96);Array.Clear(meterReceived,0,96);inputPoint=outputPoint=null;}}
}







